    // services.go:403
    pub fn get_root_symbols(&mut self, symbol: P<Symbol>) -> Vec<P<Symbol>> {
        let roots = self.get_immediate_root_symbols(symbol);
        if roots.is_empty() {
            return vec![symbol];
        }
        let mut result = Vec::new();
        for root in roots {
            result.extend(self.get_root_symbols(root));
        }
        result
    }

